let config = global.get("simConfig");
if (!config) {
    config = {
        busId: "21",
        kmlFile: "/data/kml/Homagama_138_Pettah.kml",
        speedMin: 0,
        speedMax: 60
    };
    global.set("simConfig", config);
    node.status({fill:"green",shape:"dot",text:"Config initialized"});
} else {
    node.status({fill:"blue",shape:"dot",text:"Config loaded"});
}
msg.filename = config.kmlFile;
return msg;

let kml = msg.payload;
let coordinatesStr = "";
try {
    let document = kml.kml.Document[0];

    function findCoordinates(obj) {
        if (!obj || typeof obj !== 'object') return null;
        if (obj.LineString && obj.LineString[0] && obj.LineString[0].coordinates) {
            return obj.LineString[0].coordinates[0];
        }
        for (let key of Object.keys(obj)) {
            let items = Array.isArray(obj[key]) ? obj[key] : [obj[key]];
            for (let item of items) {
                let result = findCoordinates(item);
                if (result) return result;
            }
        }
        return null;
    }

    coordinatesStr = findCoordinates(document);
    if (!coordinatesStr) throw new Error("No LineString coordinates found in KML");
} catch (e) {
    node.error("Failed to parse KML: " + e.message);
    return null;
}

let coords = coordinatesStr.trim().split(/\s+/).map(c => {
    let parts = c.split(',');
    return {
        lon: parseFloat(parts[0]),
        lat: parseFloat(parts[1])
    };
}).filter(p => !isNaN(p.lat) && !isNaN(p.lon));

flow.set("coordinates", coords);
flow.set("index", 0);
node.status({fill:"green",shape:"dot",text:"Loaded " + coords.length + " points"});
return { payload: "KML Loaded: " + coords.length + " points" };

let config = global.get("simConfig") || { busId: "21", speedMax: 60 };
let coords = flow.get("coordinates");
let index = flow.get("index") || 0;

if (!coords || coords.length === 0) {
    node.status({fill:"red",shape:"ring",text:"No coordinates loaded"});
    return null;
}

let point = coords[index];
flow.set("index", (index + 1) % coords.length);

// Restore persistent state
let speed     = flow.get("speed") || 0;
let state     = flow.get("state") || "ACCELERATING";
let stopTicks = flow.get("stopTicks") || 0;
let target    = flow.get("targetSpeed") || 35;
let nextEvent = flow.get("nextEvent") || (10 + Math.floor(Math.random() * 10));
let maxSpeed  = (config.speedMax) || 60;

function bearing(a, b) {
    let h = Math.atan2(b.lon - a.lon, b.lat - a.lat) * 180 / Math.PI;
    return h < 0 ? h + 360 : h;
}

let heading = 0, turnAngle = 0;
if (index > 0) {
    heading = bearing(coords[index - 1], point);
    if (index > 1) {
        let ph = bearing(coords[index - 2], coords[index - 1]);
        turnAngle = Math.abs(heading - ph);
        if (turnAngle > 180) turnAngle = 360 - turnAngle;
    }
}

// ---- State machine ----
if (state === "STOPPED") {
    speed = 0;
    stopTicks--;
    if (stopTicks <= 0) {
        state = "ACCELERATING";
        target = 28 + Math.random() * (maxSpeed - 28);
    }
} else {
    // Road event trigger (traffic light / bus stop / jam)
    if (index >= nextEvent && (state === "CRUISING" || state === "ACCELERATING")) {
        let roll = Math.random();
        if (roll < 0.40) {
            // Traffic light — full stop 25-75 s (5-15 ticks)
            stopTicks = 5 + Math.floor(Math.random() * 11);
            target = 0; state = "BRAKING";
        } else if (roll < 0.68) {
            // Bus stop — shorter stop 10-35 s (2-7 ticks)
            stopTicks = 2 + Math.floor(Math.random() * 6);
            target = 0; state = "BRAKING";
        } else if (roll < 0.85) {
            // Traffic jam — crawl at 3-15 km/h
            stopTicks = 0;
            target = 3 + Math.random() * 12; state = "BRAKING";
        } else {
            // Sudden hard brake (pedestrian / hazard)
            stopTicks = 1;
            target = 0; state = "BRAKING";
        }
        nextEvent = index + 10 + Math.floor(Math.random() * 22);
    }

    // Turn-based speed cap
    if (state !== "STOPPED" && state !== "BRAKING") {
        if (turnAngle > 55) {
            target = Math.min(target, 15); state = "BRAKING"; stopTicks = 0;
        } else if (turnAngle > 28) {
            target = Math.min(target, 28);
            if (speed > target + 2) state = "BRAKING";
        }
    }

    if (state === "BRAKING") {
        let rate = (target === 0) ? 12 : 6;
        speed = Math.max(target, speed - rate);
        if (speed <= 0 && target === 0) {
            speed = 0;
            if (stopTicks > 0) state = "STOPPED";
            else { state = "ACCELERATING"; target = 28 + Math.random() * (maxSpeed - 28); }
        } else if (speed <= target + 1) {
            state = "CRUISING";
        }
    } else if (state === "ACCELERATING") {
        speed = Math.min(target, speed + 4 + Math.random() * 2);
        if (speed >= target * 0.97) state = "CRUISING";
    } else {
        // CRUISING: natural micro-variation
        speed += (Math.random() - 0.48) * 3;
        speed = Math.max(target - 5, Math.min(target + 5, speed));
        // Occasional cruise speed drift
        if (Math.random() < 0.08) {
            target = Math.max(20, Math.min(maxSpeed, target + (Math.random() - 0.5) * 10));
        }
    }

    speed = Math.max(0, speed);
}

flow.set("speed", speed);
flow.set("state", state);
flow.set("stopTicks", stopTicks);
flow.set("targetSpeed", target);
flow.set("nextEvent", nextEvent);

msg.payload = {
    busId: config.busId,
    lat: point.lat,
    lon: point.lon,
    speed: Math.round(speed * 10) / 10,
    heading: Math.round(heading),
    timestamp: new Date().toISOString()
};
msg.topic = "transport/bus/" + config.busId + "/location";

let colors = { STOPPED:"red", BRAKING:"yellow", ACCELERATING:"green", CRUISING:"blue" };
let icons  = { STOPPED:"■", BRAKING:"▼", ACCELERATING:"▲", CRUISING:"→" };
node.status({ fill: colors[state]||"blue", shape:"dot",
    text: (icons[state]||"")+" "+Math.round(speed)+" km/h  "+state });
return msg;

let config = global.get("simConfig") || { busId: "21" };
msg.payload = {
    busId: config.busId,
    timestamp: new Date().toISOString()
};
msg.topic = "transport/bus/" + config.busId + "/heartbeat";
return msg;

let config = global.get("simConfig") || {
    busId: "21",
    kmlFile: "/data/kml/Homagama_138_Pettah.kml",
    speedMin: 40,
    speedMax: 50
};
msg.payload = config;
msg.statusCode = 200;
return msg;

let config = global.get("simConfig") || {};
let coords = flow.get("coordinates") || [];
let index = flow.get("index") || 0;
msg.payload = {
    running: coords.length > 0,
    totalPoints: coords.length,
    currentIndex: index,
    config: config
};
msg.statusCode = 200;
return msg;

let body = msg.payload;
let config = global.get("simConfig") || {
    busId: "21",
    kmlFile: "/data/kml/Homagama_138_Pettah.kml",
    speedMin: 40,
    speedMax: 50
};

let kmlChanged = false;

if (body.busId !== undefined) config.busId = String(body.busId);
if (body.kmlFile !== undefined) {
    kmlChanged = body.kmlFile !== config.kmlFile;
    config.kmlFile = body.kmlFile;
}
if (body.speedMin !== undefined) config.speedMin = parseFloat(body.speedMin);
if (body.speedMax !== undefined) config.speedMax = parseFloat(body.speedMax);

global.set("simConfig", config);

msg.payload = { success: true, config: config, reloading: kmlChanged };
msg.statusCode = 200;

if (kmlChanged) {
    let reloadMsg = { payload: Date.now() };
    reloadMsg.filename = config.kmlFile;
    return [msg, reloadMsg];
}
return [msg, null];
